(()=>{'use strict';const examples=[{title:'Su içmek',src:'https://videos.pexels.com/video-files/7505272/7505272-uhd_2560_1440_30fps.mp4',start:0,end:6.5,rate:1,credit:'Artem Podrez / Pexels',page:'https://www.pexels.com/video/a-girl-drinking-water-from-a-glass-7505272/'},{title:'Topu tutmak',src:'https://videos.pexels.com/video-files/8813016/8813016-uhd_2560_1440_25fps.mp4',start:0,end:4,rate:4/6.5,credit:'Kampus Production / Pexels',page:'https://www.pexels.com/video/a-boy-catching-a-football-8813016/'}];const grid=document.createElement('div');grid.className='grid';document.querySelector('main').insertBefore(grid,document.querySelector('main > .grid'));for(const e of examples){const card=document.createElement('article');card.innerHTML=`<h2>${e.title}</h2><video controls muted playsinline preload="metadata" aria-label="${e.title} örneği"></video><p>6,5 saniyelik eylem örneği</p><button type="button">Baştan izle</button><p><a href="${e.page}" target="_blank" rel="noopener">${e.credit}</a> · <a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Lisans</a></p>`;grid.append(card);const video=card.querySelector('video');video.src=e.src;video.muted=true;video.addEventListener('loadedmetadata',()=>{video.currentTime=e.start;video.playbackRate=e.rate;});const restart=()=>{if(video.currentTime>=e.end||video.currentTime<e.start)video.currentTime=e.start;};video.addEventListener('timeupdate',()=>{if(!video.paused)restart();});let frameId=null;const frame=()=>{restart();if(!video.paused&&video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(frame);};video.addEventListener('play',()=>{restart();video.playbackRate=e.rate;if(video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(frame);});video.addEventListener('pause',()=>{if(frameId!==null&&video.cancelVideoFrameCallback)video.cancelVideoFrameCallback(frameId);frameId=null;});card.querySelector('button').onclick=()=>{video.currentTime=e.start;video.play().catch(()=>{});};video.addEventListener('error',()=>{const p=document.createElement('p');p.textContent='Kaynak video yüklenemedi. Kaynak bağlantısını açabilirsiniz.';card.append(p);},{once:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();});}const heading=document.createElement('h2');heading.textContent='Kendi videonu dene';grid.after(heading);})();
